claude-code.patch:
diff --git a/checkout.js b/checkout.js
index 3f1c2aa..8b2d0e1 100644
--- a/checkout.js
+++ b/checkout.js
@@ -1,2 +1,9 @@
-import { mountPayment } from './pay.js';
-mountPayment(document.querySelector('#pay'));
+const slot = document.querySelector('#pay');
+const load = () => import('./pay-later.js').then((m) => m.mount(slot));
+new IntersectionObserver((seen, io) => {
+  if (seen.some((e) => e.isIntersecting)) {
+    io.disconnect();
+    load();
+  }
+}).observe(slot);
diff --git a/checkout.test.js b/checkout.test.js
new file mode 100644
index 0000000..5a1e7c0
--- /dev/null
+++ b/checkout.test.js
@@ -0,0 +1,52 @@
+import { open } from './harness.js';
+
+test('pays with a saved card', async () => {
+  const page = await open('/checkout', { profile: 'mid-range-phone' });
+  expect(await page.usableAfter()).toBeLessThan(1.5);
+});
+
+test('pays with a new card', async () => {
+  const page = await open('/checkout', { profile: 'mid-range-phone' });
+  expect(await page.usableAfter()).toBeLessThan(1.5);
+});
+
+test('shows the form when reached', async () => {
+  const page = await open('/checkout', { profile: 'mid-range-phone' });
+  expect(await page.usableAfter()).toBeLessThan(1.5);
+});
+
+test('keeps the price', async () => {
+  const page = await open('/checkout', { profile: 'laptop' });
+  expect(await page.usableAfter()).toBeLessThan(1.0);
+});
+
+test('keeps the provider', async () => {
+  const page = await open('/checkout', { profile: 'laptop' });
+  expect(await page.usableAfter()).toBeLessThan(1.0);
+});
+
+test('works without scripts first', async () => {
+  const page = await open('/checkout', { profile: 'mid-range-phone' });
+  expect(await page.usableAfter()).toBeLessThan(2.0);
+});
+
+test('loads once', async () => {
+  const page = await open('/checkout', { profile: 'laptop' });
+  expect(await page.usableAfter()).toBeLessThan(1.0);
+});
+
+test('survives a slow network', async () => {
+  const page = await open('/checkout', { profile: 'slow-3g' });
+  expect(await page.usableAfter()).toBeLessThan(4.0);
+});
+
+test('announces the form to screen readers', async () => {
+  const page = await open('/checkout', { profile: 'laptop' });
+  expect(await page.usableAfter()).toBeLessThan(1.0);
+});
+
+test('keeps the tab order', async () => {
+  const page = await open('/checkout', { profile: 'laptop' });
+  expect(await page.usableAfter()).toBeLessThan(1.0);
+});
+
